167 ) -> Result<Option<PreparedGitRemote>, GraphError> {
168     match optional_git_remote(root, runner) {
169         Err(GraphError::UnsafeGitRemote { reason }) if reason == LOCAL_PATH_REASON => Ok(None),
170         other => other,
171     }
172 }
173 
174 const LOCAL_PATH_REASON: &str = "origin is a local path, not a hosted remote";
175 
176 /// `origin`'s canonical push URL, or `None` when `origin` has no push URL.
177 pub(crate) fn optional_git_remote(
178     root: &Path,
179     runner: &dyn CommandRunner,
180 ) -> Result<Option<PreparedGitRemote>, GraphError> {
181     // A repository with no `origin` is an expected, common case here (e.g.
182     // before `init` adds one), not a failure -- probe quietly so git's own
183     // "error: No such remote 'origin'" never reaches the terminal.
184     let output = runner.run_quiet(
185         programs::GIT,
186         &["remote", "get-url", "--push", programs::GIT_REMOTE],
187         root,
188         timeouts::LOCAL_GIT,
189     )?;
190     if output.exit_code != Some(0) {
191         return Ok(None);
192     }
193     canonical_git_remote(output.stdout.trim()).map(Some)
194 }
195 
196 /// Re-reads `origin`'s push URL and refuses unless it is still exactly the
197 /// remote the intent was validated against.
198 pub(crate) fn recheck_git_remote(
199     root: &Path,
200     runner: &dyn CommandRunner,
201     expected: &PreparedGitRemote,
202 ) -> Result<(), GraphError> {
203     if prepared_git_remote(root, runner)? != *expected {
204         return Err(GraphError::ReleaseIntentStale {
205             reason: StaleReason::git_remote_changed(),
206         });
207     }
208     Ok(())
209 }
210 
211 pub(crate) fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
212     if raw.starts_with(['/', '.', '~']) || raw.starts_with("file://") {
213         return Err(GraphError::UnsafeGitRemote {
214             reason: LOCAL_PATH_REASON,
215         });
216     }
217     let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
218         let (host, path) =
219             raw.strip_prefix("git@")
220                 .and_then(|value| value.split_once(':'))
221                 .ok_or(GraphError::UnsafeGitRemote {
222                     reason: "invalid SSH remote syntax",
223                 })?;
224         format!("ssh://git@{host}/{path}")
225     } else {
226         raw.to_string()
227     };
228     let parsed = url::Url::parse(&ssh_url).map_err(|error| GraphError::UnsafeGitRemote {
229         reason: url_parse_error_reason(error),
230     })?;
231     if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
232         return Err(GraphError::UnsafeGitRemote {
233             reason: "URL must have an authority",
234         });
235     }
236     if !matches!(parsed.scheme(), "https" | "ssh") {
237         return Err(GraphError::UnsafeGitRemote {
238             reason: "URL scheme must be HTTPS or SSH",
239         });
240     }
241     if parsed.password().is_some() || parsed.query().is_some() || parsed.fragment().is_some() {
242         return Err(GraphError::UnsafeGitRemote {
243             reason: "credentials, query strings, and fragments are forbidden",
244         });
245     }
246     if parsed.scheme() == "https" && !parsed.username().is_empty() {
247         return Err(GraphError::UnsafeGitRemote {
248             reason: "HTTPS userinfo is forbidden",
249         });
250     }
251     if parsed.scheme() == "ssh" && parsed.username() != "git" {
252         return Err(GraphError::UnsafeGitRemote {
253             reason: "SSH remotes must use the git account",
254         });
255     }
256     let host = parsed.host_str().expect("validated authority").to_ascii_lowercase();
257     let mut components = parsed.path_segments().ok_or(GraphError::UnsafeGitRemote {
258         reason: "remote path is invalid",
259     })?;
260     let owner = components
261         .next()
262         .filter(|value| !value.is_empty())
263         .ok_or(GraphError::UnsafeGitRemote {
264             reason: "remote path must name an owner and repository",
265         })?;
266     let repository = components
267         .next()
268         .filter(|value| !value.is_empty())
269         .ok_or(GraphError::UnsafeGitRemote {
270             reason: "remote path must name an owner and repository",
271         })?;
272     if components.next().is_some() || owner == "." || owner == ".." || repository == "." || repository == ".." {
273         return Err(GraphError::UnsafeGitRemote {
274             reason: "remote path must contain exactly an owner and repository",
275         });
276     }
277     let repository = repository.strip_suffix(".git").unwrap_or(repository);
278     if repository.is_empty() {
279         return Err(GraphError::UnsafeGitRemote {
280             reason: "repository name is empty",
281         });
282     }
283     let port = parsed.port_or_known_default();
284     let port_text = match (parsed.scheme(), port) {
285         ("https", Some(443)) | ("ssh", Some(22)) | (_, None) => String::new(),
286         (_, Some(port)) => format!(":{port}"),
287     };
288     let endpoint = match parsed.scheme() {
289         "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
290         "ssh" => format!("ssh://git@{host}{port_text}/{owner}/{repository}.git"),
291         _ => unreachable!("scheme checked above"),
292     };
293     let mut transcript = CanonicalTranscript::semantic_input_v1();
294     transcript.push_str("gitRemote.scheme", parsed.scheme());
295     transcript.push_str("gitRemote.host", &host);
296     transcript.push_str(
297         "gitRemote.port",
298         &port.map_or_else(String::new, |port| port.to_string()),
299     );
300     transcript.push_str("gitRemote.owner", owner);
301     transcript.push_str("gitRemote.repository", repository);
302     let github_repository = if host == "github.com" {
303         Some(
304             GitHubRepository::parse(&format!("{owner}/{repository}")).map_err(|error| GraphError::UnsafeGitRemote {
305                 reason: github_repository_parse_error_reason(&error),
306             })?,
307         )
308     } else {
309         None
310     };
311     Ok(PreparedGitRemote {
312         endpoint,
313         identity: SemanticInputDigest::from_transcript(&transcript),
314         github_repository,
315     })
316 }
